alue="4" aria-label="Age in years"></td><td><input name="life" inputmode="decimal" value="20" aria-label="Expected life in years"></td><td class="num" data-o="row">$0</td><td><button type="button" class="rm" aria-label="Remove row">×</button></td></tr>
